mapper.update:
UPDATE ${tableName}
SET money_records = #{model.moneyRecords},
    money_apply_confirming = #{model.moneyApplyConfirming},
    new_payment_time = #{model.newPaymentTime},
    payment_time_min = #{model.paymentTimeMin},
    payment_time_max = #{model.paymentTimeMax}
WHERE primary_key = #{model.signedContractCode}
  AND enterprise_code = #{model.ownedEnterpriseCode}
  AND delete_flag = 'f' AND (canceled = false OR canceled IS NULL)

UPDATE ${tableName}
SET invoice_records = #{model.invoiceRecords},
    invoice_apply_confirming = #{model.invoiceApplyConfirming}
WHERE primary_key = #{model.signedContractCode}
  AND enterprise_code = #{model.ownedEnterpriseCode}
  AND delete_flag = 'f' AND (canceled = false OR canceled IS NULL)

