mapper.select:
SELECT primary_key, contract_amount, counterpart,identity
FROM ${tableName}
WHERE
enterprise_code = #{enterpriseCode}
AND delete_flag = 'f'

    AND counterpart LIKE '%'|| #{param.counterpart} ||'%'


    AND contract_number = #{param.contractNumber}


    AND user_code IN

        #{code}



    AND (
    (payment_time_min IS NOT NULL AND payment_time_max IS NOT NULL 
     AND payment_time_min <= #{paymentTimePost} 
     AND payment_time_max >= #{paymentTimePre}) 
    OR
    (new_payment_time IS NOT NULL 
     AND new_payment_time >= #{paymentTimePre} 
     AND new_payment_time <= #{paymentTimePost})
    )



    AND (
    (payment_time_max IS NOT NULL AND payment_time_max >= #{paymentTimePre}) 
    OR
    (new_payment_time IS NOT NULL AND new_payment_time >= #{paymentTimePre})
    )


    AND (
    (payment_time_min IS NOT NULL AND payment_time_min <= #{paymentTimePost}) 
    OR
    (new_payment_time IS NOT NULL AND new_payment_time <= #{paymentTimePost})
    )

AND (canceled  =  'false' OR canceled  IS NULL)

