mapper.select:
SELECT COALESCE(SUM(contract_amount), 0)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND contract_type = 'SELL_CONTRACT'
  AND (canceled = false OR canceled IS NULL)
  AND contract_time IS NOT NULL
  AND contract_time >= #{startDate}
  AND contract_time <= #{endDate}

SELECT COUNT(DISTINCT counterpart)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND contract_type = 'SELL_CONTRACT'
  AND (canceled = false OR canceled IS NULL)
  AND contract_time IS NOT NULL
  AND contract_time >= #{startDate}
  AND contract_time <= #{endDate}
  AND counterpart IS NOT NULL
  AND counterpart != ''

SELECT COUNT(*)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND contract_type = 'SELL_CONTRACT'
  AND (canceled = false OR canceled IS NULL)

      AND counterpart = #{counterpart}
